\set ON_ERROR_STOP on
begin;
create function pg_temp.auray_assert(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Auray monitor assertion: %',label;end if;end $$;
do $$
declare actor uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); workspace uuid; foreign_workspace uuid; wallet uuid; same_wallet uuid; job uuid; token uuid:=gen_random_uuid(); other_token uuid:=gen_random_uuid(); r jsonb; snapshot jsonb; jobs jsonb;
begin
 workspace:=public.studio_provision(actor,'Auray monitor test',false);foreign_workspace:=public.studio_provision(outsider,'Other monitor test',false);
 jobs:=jsonb_build_array(jsonb_build_object('request_key',repeat('a',64),'external_id','video_'||repeat('a',64),'label','Malu','kind','native_dialogue_probe','aspect_ratio','9:16','expected_sha256',repeat('b',64)));
 wallet:=public.register_auray_monitor(workspace,repeat('c',64),jobs);
 same_wallet:=public.register_auray_monitor(workspace,repeat('c',64),jobs);
 perform pg_temp.auray_assert(wallet=same_wallet,'same account has one physical wallet');
 perform pg_temp.auray_assert((select count(*)=1 from public.studio_auray_jobs where wallet_id=wallet),'idempotent job import');
 begin update public.studio_video_wallets set enabled=true where id=wallet;raise exception 'Candidate enabled';exception when check_violation then null;end;
 begin perform public.register_auray_monitor(foreign_workspace,repeat('c',64),jobs);raise exception 'Job transferred between workspaces';exception when check_violation then null;end;
 begin perform public.studio_video_balance_request(workspace,outsider,wallet);raise exception 'Foreign actor refreshed';exception when insufficient_privilege then null;end;
 begin perform public.studio_video_balance_request(foreign_workspace,outsider,wallet);raise exception 'Foreign workspace refreshed';exception when insufficient_privilege then null;end;
 perform pg_temp.auray_assert(public.studio_video_balance_request(workspace,actor,wallet)->>'provider'='auray','authorized Auray dispatch');
 perform pg_temp.auray_assert(public.studio_video_balance_request(workspace,actor,wallet)->>'code'='waiting','duplicate click throttled');
 r:=public.claim_auray_sync(wallet,token);perform pg_temp.auray_assert(r->>'code'='claimed','one cloud worker claims');
 perform pg_temp.auray_assert(public.claim_auray_sync(wallet,other_token)->>'code'='waiting','duplicate worker cannot collect');
 job:=(r#>>'{jobs,0,id}')::uuid;
 snapshot:=jsonb_build_object('checked_at',now(),'period',to_char(now() at time zone 'UTC','YYYY-MM'),'monthly_allowance',50,'plan_remaining',30,'key_remaining',20,'blockers','[]'::jsonb,'production_ready',false);
 begin perform public.observe_auray_monitor(wallet,other_token,snapshot);raise exception 'Stale worker observed';exception when insufficient_privilege then null;end;
 perform public.observe_auray_monitor(wallet,token,snapshot);
 r:=public.studio_video_overview(workspace,actor);
 perform pg_temp.auray_assert(r#>>'{wallets,0,remaining_units}'='30','live free balance visible');
 perform pg_temp.auray_assert(r#>>'{wallets,0,budget_only_shots}'='4','comparison respects tighter key budget');
 perform pg_temp.auray_assert(r#>>'{wallets,0,available_units}' is null and r#>>'{wallets,0,source_ready}'='false','balance does not enable production');
 perform pg_temp.auray_assert(position('account_sha256' in r::text)=0 and position('external_id' in r::text)=0 and position('expected_sha256' in r::text)=0,'overview contains no private account or provider job IDs');
 perform pg_temp.auray_assert(jsonb_array_length(public.studio_video_overview(foreign_workspace,outsider)->'wallets')=0,'wallet scoped to authorized workspace');
 begin perform public.studio_auray_media_read(workspace,actor,job);raise exception 'Unready preview returned';exception when no_data_found then null;end;
 r:=jsonb_build_object('external_id','video_'||repeat('a',64),'status','succeeded','settled',true,'charged_credits',5);
 perform public.record_auray_job(wallet,token,job,r);
 begin perform public.record_auray_job(wallet,token,job,r||jsonb_build_object('output_sha256',repeat('d',64),'bytes',100));raise exception 'Changed bytes accepted';exception when check_violation then null;end;
 perform public.record_auray_job(wallet,token,job,r||jsonb_build_object('output_sha256',repeat('b',64),'bytes',100));
 r:=public.studio_auray_media_read(workspace,actor,job);
 perform pg_temp.auray_assert(r->>'path'='auray/'||wallet||'/'||job||'/'||repeat('b',64)||'.mp4','private immutable derived path');
 begin perform public.studio_auray_media_read(foreign_workspace,outsider,job);raise exception 'Foreign preview returned';exception when no_data_found then null;end;
 perform public.finish_auray_sync(wallet,token,false);
 r:=public.studio_video_overview(workspace,actor);
 perform pg_temp.auray_assert(r#>>'{wallets,0,sync_failed}'='true' and r#>>'{wallets,0,budget_only_shots}' is null,'failed refresh hides numeric comparison');
 perform pg_temp.auray_assert(r#>>'{wallets,0,remaining_units}'='30','failed refresh preserves historical amount');
 perform public.claim_auray_sync(wallet,other_token);
 begin perform public.finish_auray_sync(wallet,token,true);raise exception 'Old worker cleared new lease';exception when insufficient_privilege then null;end;
 snapshot:=snapshot||jsonb_build_object('plan_remaining',0,'key_remaining',0,'blockers',jsonb_build_array('insufficient_free_credits'));
 perform public.observe_auray_monitor(wallet,other_token,snapshot);perform public.finish_auray_sync(wallet,other_token,true);
 r:=public.studio_video_overview(workspace,actor);
 perform pg_temp.auray_assert(r#>>'{wallets,0,remaining_units}'='0' and r#>>'{wallets,0,budget_only_shots}'='0','exhausted free balance is zero, not unknown');
 perform pg_temp.auray_assert(not exists(select 1 from public.studio_video_jobs where wallet_id=wallet),'monitor never creates production job');
 perform pg_temp.auray_assert(not has_function_privilege('authenticated','public.register_auray_monitor(uuid,text,jsonb)','execute'),'browser cannot register accounts');
 perform pg_temp.auray_assert(not has_function_privilege('authenticated','public.observe_auray_monitor(uuid,uuid,jsonb)','execute'),'browser cannot manufacture balance');
end $$;
rollback;
